use vstd::prelude::*;

verus! {
    fn rotate_right(list: &Vec<u32>, n: usize) -> (new_list: Vec<u32>)
        requires
            list.len() > 0,
            n >= 0,
        ensures
            new_list.len() == list.len(),
            forall(|i: usize| i < list.len() ==> new_list[i] == list[(len - (n % len) + i) % len]),
    {
        let len = list.len();
        let s = len - (n % len);
        let mut new_list: Vec<u32> = Vec::new();
        new_list.resize(len, 0); // Initialize new_list with the same length as list

        // Fill new_list with the rotated values
        let mut i: usize = 0;
        while i < len
            invariant
                i <= len,
                new_list.len() == len,
                forall(|j: usize| j < i ==> new_list[j] == list[(s + j) % len]),
            decreases len - i,
        {
            new_list[i] = list[(s + i) % len];
            i = i + 1;
        }

        new_list
    }
}
